package com.example

/**
 * Authentic 60-Question Health Past Paper Provider.
 * Provides 60 DISTINCT, non-repeating questions for Health for each year.
 */
object HealthPastPaper60QuestionsProvider {

    data class QuestionData(
        val topic: String,
        val text: String,
        val options: List<String>,
        val correctIdx: Int,
        val explanation: String
    )

    fun buildHealthQuestion(year: Int, qNum: Int, yearStr: String, subjectTitle: String): PastPaperQuestion {
        val q = qNum.coerceIn(1, 60)
        val yearInt = yearStr.toIntOrNull() ?: year
        
        val data = getQuestionData(q, yearInt, yearStr)
        
        return PastPaperQuestion(
            id = qNum,
            questionText = data.text,
            options = data.options,
            correctOptionIndex = data.correctIdx,
            explanationSinhala = data.explanation,
            topicCategory = data.topic,
            year = yearStr,
            subject = subjectTitle
        )
    }

    private fun getQuestionData(q: Int, yearInt: Int, yearStr: String): QuestionData {
        val questions = listOf(
            // 1-10: Physical Health & Nutrition
